-- 0009_goldiii_profiles_accessories.sql
-- Catálogo Gold III (Alcoa / Alumínio & Cia), 3 arquivos PDF cobrindo páginas
-- impressas 11-17, 19-36 (diagramas estruturais), 37-67 (perfis) e 69-105 (acessórios).
--
-- ACHADO IMPORTANTE: os códigos e cotas de usinagem citados como exemplo no pedido
-- original (FEC1028/1029, FEC1036/1038/1040/1042, "cota A/cota B") NÃO existem em
-- nenhum dos 3 arquivos enviados -- não foram inventados, ficam de fora.
-- O exemplo de compatibilidade vidro/guarnição citado no pedido ("LG015/LG050 com
-- vidro 6mm: GUA256 interna, GUA304 externa") também não bate exatamente com o
-- texto do catálogo -- a tabela real (22 combinações) está abaixo, transcrita
-- literalmente da página 104.

UPDATE technical_sources SET is_uploaded = 1, notes = 'Extração concluída: 114 perfis (LG-xxxx e outros prefixos), 94 acessórios, 22 combinações de compatibilidade vidro/guarnição (p.104). Dados estruturais Jx/Jy/Wx/Wy das páginas 19-36 documentados no relatório de extração mas ainda não carregados em structural_limits (ver docs/FONTES.md). Nenhuma cota de usinagem de fecho concha encontrada nesta fonte.' WHERE id IN (5,6,7);
UPDATE product_lines SET status_code = 'CATALOGADO', origin_type = 'ENCONTRADO_DOCUMENTO' WHERE id = 5;

