INSERT INTO profile_compatibilities (profile_id, notes, is_explicit, source_reference_id) SELECT ext.id, 'Par LG-085 (externo) / LG-026 ou BG-057 (interno), cota de encaixe 15mm, vidro 6mm -> guarnição interna GUA-256, guarnição externa GUA-304. Fonte literal: catálogo Gold III p.104. A tabela de compatibilidade (p.104) grafa o código externo como \'LG-085\'; aceita-se aqui também a grafia \'LG-0085\' (com zero extra) caso seja assim que o perfil esteja cadastrado, pois o próprio extrator já documentou essa mesma inconsistência de zero à esquerda entre páginas do catálogo para LG-018/LG-0018.', 1, @ref_compat_104 FROM profiles ext WHERE ext.manufacturer_id = 2 AND ext.code IN ('LG-085', 'LG-0085') LIMIT 1;
